create table f(id integer primary key, g text, x, y real, s text collate nocase);
insert into f(g, x, y, s) values ('a', 1, 1.5, 'b'), ('a', 2, 2.5, 'A'), ('a', 2, null, 'a'), ('a', 4, 0.25, 'C'), ('a', null, 3.0, 'c'), ('b', 10, 1.0, 'x'), ('b', 10, 2.0, 'X'), ('b', 12, -1.0, 'y'), ('b', 15, 4.5, null), ('b', 15, 0.5, 'z'), ('b', 20, null, 'Z'), ('c', 7, 7.0, 'q');
